    listPlayerCampaigns(){return this.rows('campaign_player_view','campaign_id,world_id,name,summary,player_notes,current_day,role,archived_at',query=>query.order('name'))}
    listCampaignCalendar(campaignId){return this.rows('campaign_calendar_player_view','campaign_id,world_id,current_day,calendar_year,day_of_year,season,season_day,days_until_next_season,next_season,season_warning,weather_id,card_name,public_effect,rolled_duration_days,start_day,weather_remaining_days,weather_revision',query=>query.eq('campaign_id',campaignId).limit(1))}
