    advanceCampaignTime(campaignId,expectedCurrentDay,daysToAdvance,{commandId=crypto.randomUUID()}={}){return this.rpc('advance_campaign_time',{p_campaign_id:campaignId,p_expected_current_day:expectedCurrentDay,p_days_to_advance:daysToAdvance,p_command_id:commandId})}
    recordCampaignWeather(campaignId,{expectedCurrentDay,cardName,publicEffect='',gmEffect='',rolledDurationDays=1,replaceActive=false,commandId=crypto.randomUUID()}={}){return this.rpc('record_campaign_weather',{p_campaign_id:campaignId,p_expected_current_day:expectedCurrentDay,p_card_name:cardName,p_public_effect:publicEffect,p_gm_effect:gmEffect,p_rolled_duration_days:rolledDurationDays,p_replace_active:replaceActive,p_command_id:commandId})}
    saveAstronomicalEvent(worldId,{eventId=null,expectedRevision=null,internalTitle,obviousText,lowText,mediumText,highText,observationStartDay,observationEndDay,gmNotes='',archived=false}={}){return this.rpc('save_astronomical_event',{p_world_id:worldId,p_event_id:eventId,p_expected_revision:expectedRevision,p_internal_title:internalTitle,p_obvious_text:obviousText,p_low_text:lowText,p_medium_text:mediumText,p_high_text:highText,p_observation_start_day:observationStartDay,p_observation_end_day:observationEndDay,p_gm_notes:gmNotes,p_archived:archived})}
    setCampaignAstronomicalEventRelease(campaignId,eventId,{maximumInformationLevel='obvious',expectedRevision=null,released=true}={}){return this.rpc('set_campaign_astronomical_event_release',{p_campaign_id:campaignId,p_event_id:eventId,p_maximum_information_level:maximumInformationLevel,p_expected_revision:expectedRevision,p_released:released})}
    async listManagedCampaigns(){
      const [viewRows,memberships]=await Promise.all([
        this.rows('campaign_management_view','campaign_id,world_id,name,summary,player_notes,current_day,gm_notes,role,archived_at',query=>query.order('name')),
        this.rows('campaign_memberships','campaign_id,role,status,archived_at',query=>query.in('role',['owner','game_master']).eq('status','active').is('archived_at',null))
      ]);
      const known=new Map(viewRows.map(row=>[row.campaign_id,row])),missing=memberships.filter(row=>!known.has(row.campaign_id));
      if(!missing.length)return viewRows;
      const ids=missing.map(row=>row.campaign_id),roles=new Map(missing.map(row=>[row.campaign_id,row.role])),campaigns=await this.rows('campaigns','id,world_id,name,summary,player_notes,current_day,archived_at',query=>query.in('id',ids).is('archived_at',null).order('name'));
      let secrets=[];try{secrets=await this.rows('campaign_secrets','campaign_id,gm_notes',query=>query.in('campaign_id',ids))}catch{}
      const notes=new Map(secrets.map(row=>[row.campaign_id,row.gm_notes||'']));
      for(const campaign of campaigns)known.set(campaign.id,{campaign_id:campaign.id,world_id:campaign.world_id,name:campaign.name,summary:campaign.summary||'',player_notes:campaign.player_notes||'',current_day:campaign.current_day||1,gm_notes:notes.get(campaign.id)||'',role:roles.get(campaign.id)||'game_master',archived_at:campaign.archived_at||null});
      return[...known.values()].sort((left,right)=>String(left.name||'').localeCompare(String(right.name||''),'de'))
    }
